class Inventory:
    def __init__(self):
        self.stock = {"apple": 100, "banana": 50}

    def is_available(self, item: str, quantity: int) -> bool:
        return self.stock.get(item, 0) >= quantity

    def reduce_stock(self, item: str, quantity: int):
